import{_ as i,c as s,ag as e,o as t}from"./chunks/framework.BMGgE9iy.js";const k=JSON.parse('{"title":"零大小類型","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"basic/zero-type.md","filePath":"basic/zero-type.md"}'),h={name:"basic/zero-type.md"};function n(r,a,o,d,p,l){return t(),s("div",null,a[0]||(a[0]=[e('<h1 id="零大小類型" tabindex="-1">零大小類型 <a class="header-anchor" href="#零大小類型" aria-label="Permalink to &quot;零大小類型&quot;">​</a></h1><p>在 Zig 中，有一些特殊的類型被稱為<strong>零大小類型</strong>（Zero-Sized Types），它們在內存中不佔用任何空間（0 bit）。</p><p>這些類型的特點是，它們的值不會出現在最終的構建結果中，因為它們不佔用任何內存空間。</p><h2 id="void" tabindex="-1"><code>void</code> <a class="header-anchor" href="#void" aria-label="Permalink to &quot;`void`&quot;">​</a></h2><p><code>void</code> 是一個典型的<strong>零大小類型</strong>，常用於表示函數沒有返回值。</p><p>除了作為函數返回值，<code>void</code> 還可以用於初始化泛型實例，例如 <code>std.AutoHashMap</code>：</p><div class="language-zig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">zig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> map</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AutoHashMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">testing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">allocator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>這樣可以得到一個 <code>i32</code> 類型的集合（set）。儘管可以使用其他方式實現集合功能，但這種方法可以顯著減少內存佔用，因為它不需要存儲實際的值。</p><h2 id="整數" tabindex="-1">整數 <a class="header-anchor" href="#整數" aria-label="Permalink to &quot;整數&quot;">​</a></h2><p><a href="./../basic/basic_type/number">整數</a> 聲明可以使用 <code>u0</code> 和 <code>i0</code> 來聲明<strong>零大小整數類型</strong>，它們的大小也是 0 bit。</p><h2 id="數組和切片" tabindex="-1">數組和切片 <a class="header-anchor" href="#數組和切片" aria-label="Permalink to &quot;數組和切片&quot;">​</a></h2><p><a href="./../basic/advanced_type/array">數組</a> 和 <a href="./../basic/advanced_type/slice">切片</a> 當其長度為 0 時，被視為<strong>零大小類型</strong>。</p><p>此外，如果數組或切片的元素類型本身就是零大小類型，那麼無論其長度如何，該數組或切片都將是<strong>零大小類型</strong>。</p><h2 id="枚舉" tabindex="-1">枚舉 <a class="header-anchor" href="#枚舉" aria-label="Permalink to &quot;枚舉&quot;">​</a></h2><p>只有一個成員的 <a href="./../basic/advanced_type/enum">枚舉</a> 也是<strong>零大小類型</strong>。</p><h2 id="結構體" tabindex="-1">結構體 <a class="header-anchor" href="#結構體" aria-label="Permalink to &quot;結構體&quot;">​</a></h2><p><a href="./../basic/advanced_type/struct">結構體</a> 當其為空，或者所有字段都是零大小類型時，該結構體也是<strong>零大小類型</strong>。</p><p>例如，<code>const zero = struct {};</code> 就是一個零大小類型，其大小為 0。</p><h2 id="聯合類型" tabindex="-1">聯合類型 <a class="header-anchor" href="#聯合類型" aria-label="Permalink to &quot;聯合類型&quot;">​</a></h2><h2 id="聯合類型-1" tabindex="-1">聯合類型 <a class="header-anchor" href="#聯合類型-1" aria-label="Permalink to &quot;聯合類型&quot;">​</a></h2><p>僅包含一種可能類型（且該類型是零大小類型）的 <a href="./../basic/union">聯合類型</a> 也是零大小類型。</p>',21)]))}const g=i(h,[["render",n]]);export{k as __pageData,g as default};
